function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is an integer from 1 to 10^9.';
  return null;
}

reference:
function closestFair(n) {
  for (let candidate = n; ; candidate++) {
    let odd = 0;
    let even = 0;
    for (let rest = candidate; rest > 0; rest = Math.floor(rest / 10)) {
      const digit = rest % 10;
      if (digit % 2 === 1) {
        odd++;
      } else {
        even++;
      }
    }
    const length = odd + even;
    if (length % 2 === 1) {
      const half = (length + 1) / 2;
      const ones = (10 ** (half - 1) - 1) / 9;
      return 10 ** length + ones;
    }
    if (odd === even) {
      return candidate;
    }
  }
}

brute:
function closestFair(n) {
  const isFair = k => {
    const text = String(k);
    const odds = [...text].filter(c => '13579'.includes(c)).length;
    return odds * 2 === text.length;
  };
  let k = n;
  while (!isFair(k)) {
    const size = String(k).length;
    k = size % 2 === 1 ? 10 ** size : k + 1;
  }
  return k;
}

