function generate(rand, size) {
  if (size === 'small') {
    const digits = 1 + Math.floor(rand() * 5);
    const low = 10 ** (digits - 1);
    return [low + Math.floor(rand() * (9 * low))];
  }
  const pick = rand();
  if (pick < 0.1) return [1000000000];
  if (pick < 0.25) return [100000000 + Math.floor(rand() * 900000000)];
  // Mostly 8-digit values, sometimes made of a single repeated digit so the search runs long.
  if (pick < 0.45) {
    const digit = 1 + Math.floor(rand() * 9);
    return [Number(String(digit).repeat(8))];
  }
  return [10000000 + Math.floor(rand() * 90000000)];
}
